    /// `left`
    pub const LEFT: Self = Self(1 << 2);
    /// `right`
    pub const RIGHT: Self = Self(1 << 3);
    /// `jump`
    pub const JUMP: Self = Self(1 << 4);
    /// `shift`
    pub const SHIFT: Self = Self(1 << 5);
    /// `sprint`
    pub const SPRINT: Self = Self(1 << 6);
    /// Whether every bit of `f` is set.
    #[inline]
    pub const fn contains(self, f: Self) -> bool {
        self.0 & f.0 == f.0
    }
